import React, { useState } from 'react';
import { Plus, Volume2, VolumeX, Trash2, GripVertical } from 'lucide-react';
import { DMViewProps, AudioTrack } from '../../../types/game';
import { Reorder } from 'framer-motion';

const VolumeSlider = ({ value, onChange }: { value: number; onChange: (value: number) => void }) => (
    <div className="flex items-center gap-4 w-full">
      <span className="font-['Mohave']">Volume</span>
      <input
        type="range"
        min="0"
        max="100"
        value={value}
        onChange={(e) => onChange(Number(e.target.value))}
        className="flex-1 h-2 rounded appearance-none bg-grey/10 dark:bg-offwhite/10
          [&::-webkit-slider-thumb]:appearance-none
          [&::-webkit-slider-thumb]:w-14
          [&::-webkit-slider-thumb]:h-6
          [&::-webkit-slider-thumb]:rounded-full
          [&::-webkit-slider-thumb]:bg-blue
          [&::-webkit-slider-thumb]:dark:bg-cyan
          [&::-webkit-slider-thumb]:cursor-pointer
          [&::-webkit-slider-thumb]:border-none
          [&::-moz-range-thumb]:w-4
          [&::-moz-range-thumb]:h-4
          [&::-moz-range-thumb]:rounded-full
          [&::-moz-range-thumb]:bg-blue
          [&::-moz-range-thumb]:dark:bg-cyan
          [&::-moz-range-thumb]:cursor-pointer
          [&::-moz-range-thumb]:border-none
          [&::-webkit-slider-runnable-track]:rounded
          [&::-moz-range-track]:bg-blue/20
          [&::-moz-range-track]:dark:bg-cyan/20
          [&::-moz-range-track]:rounded"
      />
      <span className="w-12 font-['Mohave']">{value}%</span>
    </div>
  );

function isValidYoutubeUrl(url: string) {
    // More permissive pattern that allows for query parameters
    const pattern = /^(?:https?:\/\/)?(?:www\.|m\.)?(youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/)([a-zA-Z0-9_-]+).*$/;
    return pattern.test(url);
  }
  
  function extractYoutubeId(url: string) {
    // Extract ID from various URL formats, ignoring additional parameters
    const fullPattern = /(?:youtube\.com\/(?:watch\?v=|embed\/)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const match = url.match(fullPattern);
    return match ? match[1] : null;
  }

  async function getVideoTitle(url: string): Promise<string | null> {
    try {
      const videoId = extractYoutubeId(url);
      if (!videoId) return null;
  
      const response = await fetch(`https://noembed.com/embed?url=https://www.youtube.com/watch?v=${videoId}`);
      const data = await response.json();
      return data.title || null;
    } catch (error) {
      console.error('Failed to fetch video title:', error);
      return null;
    }
  }

  const colorOptions = [
    { name: '⚪', value: 'bg-grey/5' },
    { name: '🔵', value: 'bg-blue/20' },
    { name: '🟣', value: 'bg-purple/20' },
    { name: '🔴', value: 'bg-red/20' }
  ];
  
  export function AudioTab({ gameState, onGameStateChange, room, isRoomCreator }: DMViewProps) {
    const [newTrackUrl, setNewTrackUrl] = useState('');
  const [newTrackName, setNewTrackName] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  
  const handleAddTrack = async () => {
    setError(null);
    setIsLoading(true);

    try {
      if (!isValidYoutubeUrl(newTrackUrl)) {
        setError('Invalid YouTube URL');
        return;
      }

      const youtubeId = extractYoutubeId(newTrackUrl);
      if (!youtubeId) {
        setError('Could not extract YouTube video ID');
        return;
      }

      // If no name provided, fetch video title
      let trackName = newTrackName;
      if (!trackName.trim()) {
        const title = await getVideoTitle(newTrackUrl);
        if (title) {
          trackName = title;
        } else {
          trackName = 'Untitled Track';
        }
      }

      const newTrack: AudioTrack = {
        id: crypto.randomUUID(),
        youtubeId,
        name: trackName,
        url: newTrackUrl,
        status: 'loading',
        color: colorOptions[0].value
      };

      onGameStateChange({
        ...gameState,
        audio: {
          ...gameState.audio,
          playlist: [...gameState.audio.playlist, newTrack]
        }
      });

      setNewTrackUrl('');
      setNewTrackName('');
    } catch (error) {
      setError('Failed to add track. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };
  
    const handleDeleteTrack = (trackId: string) => {
      if (trackId === 'silence') return; // Prevent deleting silence
  
      onGameStateChange({
        ...gameState,
        audio: {
          ...gameState.audio,
          currentTrackId: gameState.audio.currentTrackId === trackId ? 'silence' : gameState.audio.currentTrackId,
          playlist: gameState.audio.playlist.filter(track => track.id !== trackId)
        }
      });
    };
  
    const handleReorderPlaylist = (reorderedPlaylist: AudioTrack[]) => {
      onGameStateChange({
        ...gameState,
        audio: {
          ...gameState.audio,
          playlist: reorderedPlaylist
        }
      });
    };
  
    const handleColorChange = (trackId: string, color: string) => {
      onGameStateChange({
        ...gameState,
        audio: {
          ...gameState.audio,
          playlist: gameState.audio.playlist.map(track =>
            track.id === trackId ? { ...track, color } : track
          )
        }
      });
    };
  
    const currentTrack = gameState.audio.playlist.find(
      track => track.id === gameState.audio.currentTrackId
    );
  
    return (
      <div className="w-full h-full p-4 flex gap-4">
        {/* Left Side - Track List */}
        <div className="w-2/3 h-full flex flex-col">
          <h2 className="text-xl font-['BrunoAceSC'] mb-4">Playlist</h2>
          <Reorder.Group 
            axis="y" 
            values={gameState.audio.playlist} 
            onReorder={handleReorderPlaylist}
            className="flex-1 space-y-2 overflow-y-auto pr-2"
          >
            {gameState.audio.playlist.map((track) => (
              <Reorder.Item
                key={track.id}
                value={track}
                className={`
                  rounded-lg p-4 flex items-center gap-4
                  ${track.color || colorOptions[0].value}
                  ${track.id === gameState.audio.currentTrackId ? 'border-2 border-blue dark:border-cyan' : ''}
                  transition-colors duration-200
                `}
              >
                <GripVertical className="cursor-move w-5 h-5 opacity-50" />
                <button
                  className="flex-1 flex items-center gap-4 text-left"
                  onClick={() => onGameStateChange({
                    ...gameState,
                    audio: {
                      ...gameState.audio,
                      currentTrackId: track.id
                    }
                  })}
                >
                  {track.id === gameState.audio.currentTrackId ? (
                    <Volume2 className="w-5 h-5" />
                  ) : (
                    <div className="w-5" />
                  )}
                  <span className="font-['Mohave'] text-lg">{track.name}</span>
                </button>
                
                {/* Color Selector */}
                {track.id !== 'silence' && (
                    <select
                        value={track.color || colorOptions[0].value}
                        onChange={(e) => handleColorChange(track.id, e.target.value)}
                        className="bg-transparent border-none text-grey dark:text-offwhite 
                        [&>option]:text-grey [&>option]:bg-offwhite 
                        dark:[&>option]:text-offwhite dark:[&>option]:bg-grey"
                    >
                        {colorOptions.map(option => (
                        <option key={option.value} value={option.value}>
                            {option.name}
                        </option>
                        ))}
                    </select>
                    )}
  
                {/* Delete Button */}
                {track.id !== 'silence' && (
                  <button
                    onClick={() => handleDeleteTrack(track.id)}
                    className="p-2 hover:bg-red-500/10 rounded-lg transition-colors"
                  >
                    <Trash2 className="w-5 h-5" />
                  </button>
                )}
              </Reorder.Item>
            ))}
          </Reorder.Group>
        </div>
  
        {/* Right Side */}
        <div className="w-1/3 h-full flex flex-col gap-4">
          {/* Top Right - Current Track */}
          <div className="p-6 rounded-xl bg-grey/5 dark:bg-offwhite/5 border-2 border-grey dark:border-offwhite">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-4">
                {gameState.audio.currentTrackId === 'silence' ? (
                  <VolumeX className="w-8 h-8" />
                ) : (
                  <Volume2 className="w-8 h-8" />
                )}
                <div>
                  <h3 className="text-xl font-['BrunoAceSC']">Now Playing</h3>
                  <p className="text-lg font-['Mohave']">
                    {currentTrack?.name || 'No track selected'}
                  </p>
                </div>
              </div>
            </div>
  
            {/* Volume Control */}
            <VolumeSlider
                value={gameState.audio.volume}
                onChange={(newValue) => onGameStateChange({
                    ...gameState,
                    audio: {
                    ...gameState.audio,
                    volume: newValue
                    }
                })}
                />
          </div>
  
          {/* Bottom Right - Add Track Form */}
          <div className="flex-1 p-6 rounded-xl bg-grey/5 dark:bg-offwhite/5 border-2 border-grey dark:border-offwhite">
            <h3 className="text-xl font-['BrunoAceSC'] mb-4">Add New Track</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-1">Track Name (Optional)</label>
                <input
                  type="text"
                  value={newTrackName}
                  onChange={(e) => setNewTrackName(e.target.value)}
                  placeholder="Enter track name..."
                  className="w-full px-4 py-2 rounded-lg border-2 border-grey dark:border-offwhite bg-transparent"
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">YouTube URL</label>
                <input
                  type="text"
                  value={newTrackUrl}
                  onChange={(e) => setNewTrackUrl(e.target.value)}
                  placeholder="https://youtube.com/watch?v=..."
                  className="w-full px-4 py-2 rounded-lg border-2 border-grey dark:border-offwhite bg-transparent"
                />
              </div>
              {error && (
                <div className="text-red-500 dark:text-red-400 text-sm">
                  {error}
                </div>
              )}
              <button
                onClick={handleAddTrack}
                disabled={isLoading}
                className="w-full px-6 py-2 rounded-lg bg-blue hover:bg-blue-600 dark:bg-cyan dark:hover:bg-cyan-600 text-white dark:text-grey flex items-center justify-center gap-2 disabled:opacity-50"
                >
                {isLoading ? (
                    <span>Adding Track...</span>
                ) : (
                    <>
                    <Plus className="w-5 h-5" />
                    Add Track
                    </>
                )}
                </button>
            </div>
          </div>
        </div>
      </div>
    );
  }