import React, { useState, useRef } from 'react';
import { GameState, Item, Skill } from '../../../types/game';
import { useItemActions } from '../../../actions/itemActions';
import { useSkillActions } from '../../../actions/skillActions';
import { CatalogTabs, CatalogTabsList, CatalogTabsTrigger, CatalogTabsContent } from '../../ui/CatalogTabs';
import { CoolTabs, CoolTabsList, CoolTabsTrigger, CoolTabsContent } from '../../ui/cooltabs';
import BasicObjectView from '../../ui/BasicObjectView';
import { ItemView } from '../../shared/ItemView';
import { SkillView } from '../../shared/SkillView';
import { ItemEditor } from '../ItemEditor';
import { SkillEditor } from '../SkillEditor';
import Modal from '../../shared/Modal';
import { ChevronLeft, ChevronRight } from 'lucide-react';

interface CatalogTabProps {
  gameState: GameState;
  onGameStateChange: (newState: GameState) => void;
  room?: Room;
}

export function CatalogTab({ gameState, onGameStateChange, room }: CatalogTabProps) {
  // Selected recipients state
  const [selectedRecipientIds, setSelectedRecipientIds] = useState<Set<string>>(new Set());
  const [selectedRecipientType, setSelectedRecipientType] = useState<'character' | 'globalEntity' | 'fieldEntity'>('character');
  
  // Scroll container ref
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  
  // Modal states for items
  const [showCreateItem, setShowCreateItem] = useState(false);
  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  
  // Modal states for skills
  const [showCreateSkill, setShowCreateSkill] = useState(false);
  const [selectedSkill, setSelectedSkill] = useState<Skill | null>(null);

  // Get actions
  const itemActions = useItemActions(room, gameState, onGameStateChange, true);
  const skillActions = useSkillActions(room, gameState, onGameStateChange, true);

  const handleScroll = (direction: 'left' | 'right') => {
    if (!scrollContainerRef.current) return;
    
    const scrollAmount = 300; // Adjust this value to control scroll distance
    const container = scrollContainerRef.current;
    const targetScroll = container.scrollLeft + (direction === 'left' ? -scrollAmount : scrollAmount);
    
    container.scrollTo({
      left: targetScroll,
      behavior: 'smooth'
    });
  };

  const handleRecipientSelect = (recipientId: string) => {
    setSelectedRecipientIds(prev => {
      const newSet = new Set(prev);
      if (newSet.has(recipientId)) {
        newSet.delete(recipientId);
      } else {
        newSet.add(recipientId);
      }
      return newSet;
    });
  };

  const handleGiveItem = (item: Item) => {
    if (selectedRecipientIds.size === 0 || !itemActions?.giveItem) return;
    
    selectedRecipientIds.forEach(recipientId => {
      if (itemActions?.giveItem) {
        itemActions.giveItem(item.id, recipientId, selectedRecipientType);
      }
    });
  };
  
  const handleGrantSkill = (skill: Skill) => {
    if (selectedRecipientIds.size === 0 || !skillActions?.grantSkill) return;
    
    selectedRecipientIds.forEach(recipientId => {
      if (skillActions?.grantSkill) {
        skillActions.grantSkill(skill.id, recipientId, selectedRecipientType);
      }
    });
  };

  const handleCreateItem = async (itemData: Omit<Item, 'id'>) => {
    if (!itemActions?.createItem) return;
    
    try {
      await itemActions.createItem(itemData);
      setShowCreateItem(false);
    } catch (error) {
      console.error('Failed to create item:', error);
    }
  };

  const handleCreateSkill = async (skillData: Omit<Skill, 'id'>) => {
    if (!skillActions?.createSkill) return;
    
    try {
      await skillActions.createSkill(skillData);
      setShowCreateSkill(false);
    } catch (error) {
      console.error('Failed to create skill:', error);
    }
  };

  const renderRecipientList = () => {
    let recipients: { id: string; name: string; image?: string }[] = [];
    
    switch (selectedRecipientType) {
      case 'character':
        recipients = gameState.party;
        break;
      case 'globalEntity':
        recipients = gameState.globalCollections.entities;
        break;
      case 'fieldEntity':
        recipients = gameState.field;
        break;
    }

    return (
      <div className="h-full w-full flex flex-col">
        <div className="flex-1 min-h-0 relative">
          <div className="absolute inset-0 border-[length:3px] rounded-xl border-grey dark:border-offwhite flex items-center">
            {/* Left Arrow */}
            <button 
              className="absolute left-2 z-10 py-2 rounded-lg bg-grey/20 dark:bg-offwhite/20 hover:bg-grey/30 dark:hover:bg-offwhite/30 transition-colors"
              onClick={() => handleScroll('left')}
            >
              <ChevronLeft className="w-6 h-6" />
            </button>

            {/* Scrollable Container */}
            <div 
              ref={scrollContainerRef}
              className="h-full w-full flex overflow-x-auto overflow-y-hidden p-4 px-12 gap-4 items-center scrollbar-hide"
              style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
            >
              {recipients.map(recipient => (
                <div key={recipient.id} className="flex-shrink-0">
                  <BasicObjectView
                    name={recipient.name}
                    imageId={recipient.image}
                    size="md"
                    onClick={() => handleRecipientSelect(recipient.id)}
                    border={{
                      width: selectedRecipientIds.has(recipient.id) ? 4 : 2,
                      color: selectedRecipientIds.has(recipient.id) ? 'var(--color-blue)' : undefined
                    }}
                  />
                </div>
              ))}
              {recipients.length === 0 && (
                <div className="flex items-center justify-center text-gray-500 w-full">
                  No {selectedRecipientType === 'character' ? 'characters' : 'entities'} available
                </div>
              )}
            </div>

            {/* Right Arrow */}
            <button 
              className="absolute right-2 z-10 py-2 rounded-lg bg-grey/20 dark:bg-offwhite/20 hover:bg-grey/30 dark:hover:bg-offwhite/30 transition-colors"
              onClick={() => handleScroll('right')}
            >
              <ChevronRight className="w-6 h-6" />
            </button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div 
      className="grid h-full w-full"
      style={{
        gridTemplateRows: '30fr 70fr',
        gap: '0',
        padding: '1vh'
      }}
    >
      {/* Recipients Section - Top 30% */}
      <div className="w-full flex flex-col px-4">
        <CatalogTabs defaultValue="characters" className="flex-1 flex flex-col">
          <CatalogTabsList className="flex-shrink-0">
            <CatalogTabsTrigger 
              value="characters" 
              onClick={() => setSelectedRecipientType('character')}
            >
              Characters
            </CatalogTabsTrigger>
            <CatalogTabsTrigger 
              value="globalEntities" 
              onClick={() => setSelectedRecipientType('globalEntity')}
            >
              Global Entities
            </CatalogTabsTrigger>
            <CatalogTabsTrigger 
              value="fieldEntities" 
              onClick={() => setSelectedRecipientType('fieldEntity')}
            >
              Field Entities
            </CatalogTabsTrigger>
          </CatalogTabsList>

          <div className="flex-1 min-h-0 px-8">
            {renderRecipientList()}
          </div>
        </CatalogTabs>
      </div>

      {/* Items/Skills Section - Bottom 70% */}
      <div className="w-full min-h-0 p-2">
        <CoolTabs defaultValue="items" className="h-full flex flex-col">
          <CoolTabsList className="flex-shrink-0">
            <CoolTabsTrigger value="items" tabType="inventory">Items</CoolTabsTrigger>
            <CoolTabsTrigger value="skills" tabType="skills">Skills</CoolTabsTrigger>
          </CoolTabsList>

          <div className="flex-1 min-h-0">
            <CoolTabsContent value="items" className="h-full">
              <div className="h-full overflow-y-auto">
                <div className="flex flex-wrap justify-center gap-12 p-4 items-start content-start min-w-0">
                  <BasicObjectView
                    name="Create New Item"
                    size="md"
                    action={{
                      onClick: () => setShowCreateItem(true),
                      icon: 'arrow'
                    }}
                  />
                  {gameState.globalCollections.items.map(item => (
                    <BasicObjectView
                      key={item.id}
                      name={item.name}
                      imageId={item.image}
                      size="md"
                      onClick={() => setSelectedItem(item)}
                      action={{
                        onClick: () => handleGiveItem(item),
                        icon: 'plus',
                        disabled: selectedRecipientIds.size === 0
                      }}
                    />
                  ))}
                </div>
              </div>
            </CoolTabsContent>

            <CoolTabsContent value="skills" className="h-full">
              <div className="h-full overflow-y-auto">
                <div className="flex flex-wrap justify-center gap-12 p-4 items-start content-start min-w-0">
                  <BasicObjectView
                    name="Create New Skill"
                    size="md"
                    action={{
                      onClick: () => setShowCreateSkill(true),
                      icon: 'arrow'
                    }}
                  />
                  {gameState.globalCollections.skills.map(skill => (
                    <BasicObjectView
                      key={skill.id}
                      name={skill.name}
                      imageId={skill.image}
                      size="md"
                      onClick={() => setSelectedSkill(skill)}
                      action={{
                        onClick: () => handleGrantSkill(skill),
                        icon: 'plus',
                        disabled: selectedRecipientIds.size === 0
                      }}
                    />
                  ))}
                </div>
              </div>
            </CoolTabsContent>
          </div>
        </CoolTabs>
      </div>

      {/* Modals */}
      {showCreateItem && (
        <Modal
          isOpen={showCreateItem}
          onClose={() => setShowCreateItem(false)}
          title="Create New Item"
        >
          <ItemEditor
            onSubmit={handleCreateItem}
            onCancel={() => setShowCreateItem(false)}
          />
        </Modal>
      )}

      {showCreateSkill && (
        <Modal
          isOpen={showCreateSkill}
          onClose={() => setShowCreateSkill(false)}
          title="Create New Skill"
        >
          <SkillEditor
            onSubmit={handleCreateSkill}
            onCancel={() => setShowCreateSkill(false)}
          />
        </Modal>
      )}

      {selectedItem && (
        <Modal
          isOpen={!!selectedItem}
          onClose={() => setSelectedItem(null)}
          title={selectedItem.name}
        >
          <ItemView
            item={selectedItem}
            onClose={() => setSelectedItem(null)}
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            room={room}
            isRoomCreator={true}
          />
        </Modal>
      )}

      {selectedSkill && (
        <Modal
          isOpen={!!selectedSkill}
          onClose={() => setSelectedSkill(null)}
          title={selectedSkill.name}
        >
          <SkillView
            skill={selectedSkill}
            onClose={() => setSelectedSkill(null)}
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            room={room}
            isRoomCreator={true}
          />
        </Modal>
      )}
    </div>
  );
}