import React, { useState, useEffect } from 'react';
import { Skill } from '../../types/game';
import { imageManager } from '../../services/ImageManager';
import { X } from 'lucide-react';

interface SkillEditorProps {
  skill?: Skill;  // Optional skill for editing mode
  onSubmit: (skill: Omit<Skill, 'id'>) => void;
  onCancel: () => void;
}

export const SkillEditor: React.FC<SkillEditorProps> = ({ skill, onSubmit, onCancel }) => {
  const [form, setForm] = useState<Omit<Skill, 'id'>>({
    name: '',
    description: '',
    damage: 0,
    spCost: 0,
  });
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [tags, setTags] = useState<string[]>(skill?.tags ?? []);
  const [currentTag, setCurrentTag] = useState('');
  const [uses, setUses] = useState<number | undefined>(skill?.uses);

  useEffect(() => {
    if (skill) {
      const { id, ...skillData } = skill;
      setForm(skillData);
      setTags(skillData.tags ?? []);
      setUses(skillData.uses);

      if (skillData.image) {
        const thumbnail = imageManager.getThumbnail(skillData.image);
        if (thumbnail) {
          setImagePreview(thumbnail);
        }
      }
    }
  }, [skill]);

  const addCurrentTag = () => {
    if (currentTag.trim()) {
      setTags(prevTags => [...prevTags, currentTag.trim()]);
      setCurrentTag('');
    }
  };

  const handleAddTag = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' || e.key === ',') {
      e.preventDefault();
      addCurrentTag();
    }
  };

  const handleTagBlur = () => {
    addCurrentTag();
  };

  const handleRemoveTag = (tagToRemove: string) => {
    setTags(tags.filter(tag => tag !== tagToRemove));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      setErrors(prev => ({ ...prev, image: 'Please upload an image file' }));
      return;
    }

    const MAX_SIZE = 5 * 1024 * 1024; // 5MB
    if (file.size > MAX_SIZE) {
      setErrors(prev => ({ ...prev, image: 'Image must be smaller than 5MB' }));
      return;
    }

    try {
      setIsUploading(true);
      const imageData = await imageManager.addImage(file);
      setImagePreview(imageData.thumbnail);
      setForm(prev => ({ ...prev, image: imageData.id }));
      setIsUploading(false);
      setErrors(prev => {
        const { image, ...rest } = prev;
        return rest;
      });
    } catch (error) {
      console.error('Error uploading image:', error);
      setErrors(prev => ({ ...prev, image: 'Failed to upload image' }));
      setIsUploading(false);
    }
  };

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!form.name.trim()) {
      newErrors.name = 'Name is required';
    }

    if (!form.description.trim()) {
      newErrors.description = 'Description is required';
    }

    if (form.damage < 0) {
      newErrors.damage = 'Damage cannot be negative';
    }

    if (form.spCost < 0) {
      newErrors.spCost = 'SP Cost cannot be negative';
    }

    if (uses !== undefined && uses < 1) {
      newErrors.uses = 'Uses must be at least 1';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateForm()) return;

    onSubmit({
      ...form,
      tags,
      uses,
      usesLeft: uses // Initialize usesLeft to maximum uses
    });
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4 p-4">
      <div>
        <label className="block text-sm font-medium mb-1">Name</label>
        <input
          type="text"
          value={form.name}
          onChange={e => {
            setForm(prev => ({ ...prev, name: e.target.value }));
            if (errors.name) {
              setErrors(prev => {
                const { name, ...rest } = prev;
                return rest;
              });
            }
          }}
          className={`w-full p-2 border rounded ${
            errors.name ? 'border-red-500' : 'border-gray-300'
          }`}
          required
        />
        {errors.name && <p className="mt-1 text-sm text-red-500">{errors.name}</p>}
      </div>

      <div>
        <label className="block text-sm font-medium mb-1">Description</label>
        <textarea
          value={form.description}
          onChange={e => {
            setForm(prev => ({ ...prev, description: e.target.value }));
            if (errors.description) {
              setErrors(prev => {
                const { description, ...rest } = prev;
                return rest;
              });
            }
          }}
          className={`w-full p-2 border rounded ${
            errors.description ? 'border-red-500' : 'border-gray-300'
          }`}
          rows={3}
          required
        />
        {errors.description && <p className="mt-1 text-sm text-red-500">{errors.description}</p>}
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-medium mb-1">Damage</label>
          <input
            type="number"
            value={form.damage}
            onChange={e => {
              setForm(prev => ({ ...prev, damage: Number(e.target.value) }));
              if (errors.damage) {
                setErrors(prev => {
                  const { damage, ...rest } = prev;
                  return rest;
                });
              }
            }}
            className={`w-full p-2 border rounded ${
              errors.damage ? 'border-red-500' : 'border-gray-300'
            }`}
            min="0"
            required
          />
          {errors.damage && <p className="mt-1 text-sm text-red-500">{errors.damage}</p>}
        </div>

        <div>
          <label className="block text-sm font-medium mb-1">SP Cost</label>
          <input
            type="number"
            value={form.spCost}
            onChange={e => {
              setForm(prev => ({ ...prev, spCost: Number(e.target.value) }));
              if (errors.spCost) {
                setErrors(prev => {
                  const { spCost, ...rest } = prev;
                  return rest;
                });
              }
            }}
            className={`w-full p-2 border rounded ${
              errors.spCost ? 'border-red-500' : 'border-gray-300'
            }`}
            min="0"
            required
          />
          {errors.spCost && <p className="mt-1 text-sm text-red-500">{errors.spCost}</p>}
        </div>
      </div>

      <div>
        <label className="block text-sm font-medium mb-1">Uses (leave empty for unlimited)</label>
        <input
          type="number"
          value={uses ?? ''}
          onChange={e => {
            const value = e.target.value ? Number(e.target.value) : undefined;
            setUses(value);
            if (errors.uses) {
              setErrors(prev => {
                const { uses, ...rest } = prev;
                return rest;
              });
            }
          }}
          className={`w-full p-2 border rounded ${
            errors.uses ? 'border-red-500' : 'border-gray-300'
          }`}
          min="1"
          placeholder="Unlimited"
        />
        {errors.uses && <p className="mt-1 text-sm text-red-500">{errors.uses}</p>}
      </div>

      <div>
        <label className="block text-sm font-medium mb-1">Tags</label>
        <div className="flex flex-wrap gap-2 mb-2">
          {tags.map(tag => (
            <span 
              key={tag}
              className="px-2 py-1 bg-blue-100 text-blue-800 rounded-md flex items-center gap-1"
            >
              {tag}
              <button
                type="button"
                onClick={() => handleRemoveTag(tag)}
                className="hover:text-blue-600"
              >
                <X className="h-3 w-3" />
              </button>
            </span>
          ))}
        </div>
        <input
          type="text"
          value={currentTag}
          onChange={e => setCurrentTag(e.target.value)}
          onKeyDown={handleAddTag}
          onBlur={handleTagBlur}
          placeholder="Type a tag and press Enter (e.g., 'Fire', 'AoE')"
          className="w-full p-2 border rounded"
        />
      </div>

      <div>
        <label className="block text-sm font-medium mb-1">Skill Image</label>
        {imagePreview && (
          <div className="mt-2 relative w-32 h-32">
            <img
              src={imagePreview}
              alt="Skill preview"
              className="w-full h-full object-cover rounded-md"
            />
            <button
              type="button"
              onClick={() => {
                setImagePreview(null);
                setForm(prev => ({ ...prev, image: undefined }));
              }}
              className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center"
            >
              ×
            </button>
          </div>
        )}

        <input
          type="file"
          accept="image/*"
          onChange={handleImageUpload}
          disabled={isUploading}
          className="block w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100"
        />
        {isUploading && <p className="text-sm text-gray-500 mt-1">Uploading...</p>}
        {errors.image && <p className="mt-1 text-sm text-red-500">{errors.image}</p>}
      </div>

      <div className="flex justify-end gap-2">
        <button
          type="button"
          onClick={onCancel}
          className="px-4 py-2 border rounded"
        >
          Cancel
        </button>
        <button
          type="submit"
          className="px-4 py-2 bg-blue-600 text-white rounded disabled:bg-blue-300"
          disabled={isUploading}
        >
          {skill ? 'Update Skill' : 'Create Skill'}
        </button>
      </div>
    </form>
  );
};