import React, { useState, useEffect } from 'react';
import { Item } from '../../types/game';
import { imageManager } from '../../services/ImageManager';
import { X } from 'lucide-react';

interface ItemEditorProps {
  item?: Item;  // Optional item for editing mode
  onSubmit: (item: Omit<Item, 'id'>) => void;
  onCancel: () => void;
}

export const ItemEditor: React.FC<ItemEditorProps> = ({item, onSubmit, onCancel }) => {
    // Initialize state with item values if provided
  const [name, setName] = useState(item?.name ?? '');
  const [description, setDescription] = useState(item?.description ?? '');
  const [isEquippable, setIsEquippable] = useState(item?.isEquippable ?? false);
  const [uses, setUses] = useState<number | undefined>(item?.uses);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [image, setImage] = useState<string | undefined>(item?.image);
  const [isUploadingImage, setIsUploadingImage] = useState(false);
  const [tags, setTags] = useState<string[]>(item?.tags ?? []);
  const [currentTag, setCurrentTag] = useState('');

// Load image preview if item has an image
useEffect(() => {
  if (item?.image) {
    const thumbnail = imageManager.getThumbnail(item.image);
    if (thumbnail) {
      setImagePreview(thumbnail);
    }
  }
}, [item?.image]);

    const addCurrentTag = () => {
      if (currentTag.trim()) {
        setTags(prevTags => [...prevTags, currentTag.trim()]);
        setCurrentTag('');
      }
    };

    const handleAddTag = (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === 'Enter' || e.key === ',') {
        e.preventDefault();
        addCurrentTag();
      }
    };

    const handleTagBlur = () => {
      addCurrentTag();
    };

    const handleRemoveTag = (tagToRemove: string) => {
      setTags(tags.filter(tag => tag !== tagToRemove));
    };

    const handleSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      // Include current tag if it exists
      const finalTags = currentTag.trim() 
        ? [...tags, currentTag.trim()] 
        : tags;
      onSubmit({ 
        name, 
        description, 
        isEquippable, 
        uses, 
        image, 
        tags: finalTags 
      });
    };
  
    const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (!file) return;
  
      if (!file.type.startsWith('image/')) {
        // Could add error handling here
        return;
      }
  
      const MAX_SIZE = 5 * 1024 * 1024; // 5MB
      if (file.size > MAX_SIZE) {
        // Could add error handling here
        return;
      }
  
      try {
        setIsUploadingImage(true);
  
        // Store in ImageManager
        const imageData = await imageManager.addImage(file);
        
        // Set the image ID and preview
        setImage(imageData.id);
        setImagePreview(imageData.thumbnail);
        
        setIsUploadingImage(false);
      } catch (error) {
        console.error('Error uploading image:', error);
        setIsUploadingImage(false);
      }
    };
  
    return (
      <form onSubmit={handleSubmit} className="space-y-4 p-4">
        <div>
          <label className="block text-sm font-medium mb-1">Name</label>
          <input
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            className="w-full p-2 border rounded"
            required
          />
        </div>
        <div>
          <label className="block text-sm font-medium mb-1">Description</label>
          <textarea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            className="w-full p-2 border rounded"
            required
          />
        </div>
        <div>
          <label className="block text-sm font-medium mb-1">Tags</label>
          <div className="flex flex-wrap gap-2 mb-2">
            {tags.map(tag => (
              <span 
                key={tag}
                className="px-2 py-1 bg-blue-100 text-blue-800 rounded-md flex items-center gap-1"
              >
                {tag}
                <button
                  type="button"
                  onClick={() => handleRemoveTag(tag)}
                  className="hover:text-blue-600"
                >
                  <X className="h-3 w-3" />
                </button>
              </span>
            ))}
          </div>
          <input
            type="text"
            value={currentTag}
            onChange={(e) => setCurrentTag(e.target.value)}
            onKeyDown={handleAddTag}
            onBlur={handleTagBlur}
            placeholder="Type a tag and press Enter (e.g., 'Location: City')"
            className="w-full p-2 border rounded"
          />
          <p className="text-sm text-gray-500 mt-1">
            Press Enter or comma (,) to add a tag
          </p>
        </div>
        <div>
          <label className="block text-sm font-medium mb-1">Item Image</label>
          {imagePreview && (
            <div className="mt-2 relative w-32 h-32">
              <img
                src={imagePreview}
                alt="Item preview"
                className="w-full h-full object-cover rounded-md"
                onError={() => setImagePreview(null)}
              />
              <button
                type="button"
                onClick={() => {
                  setImagePreview(null);
                  setImage(undefined);
                }}
                className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center"
              >
                ×
              </button>
            </div>
          )}
          <div>
            <input
              type="file"
              accept="image/*"
              onChange={handleImageUpload}
              disabled={isUploadingImage}
              className="block w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100"
            />
            {isUploadingImage && (
              <p className="text-sm text-gray-500 mt-1">Uploading...</p>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2">
          <input
            type="checkbox"
            checked={isEquippable}
            onChange={(e) => setIsEquippable(e.target.checked)}
            id="isEquippable"
          />
          <label htmlFor="isEquippable">Is Equippable</label>
        </div>
        <div>
          <label className="block text-sm font-medium mb-1">Uses (optional)</label>
          <input
            type="number"
            value={uses ?? ''}
            onChange={(e) => setUses(e.target.value ? Number(e.target.value) : undefined)}
            className="w-full p-2 border rounded"
            min="1"
          />
        </div>
        <div className="flex justify-end gap-2">
          <button type="button" onClick={onCancel} className="px-4 py-2 border rounded">Cancel</button>
          <button 
            type="submit" 
            className="px-4 py-2 bg-blue-600 text-white rounded"
            disabled={isUploadingImage}
          >
            {item ? 'Update' : 'Create'}
          </button>
        </div>
      </form>
    );
};