import React, { ReactNode, useEffect } from 'react';
import type { ConnectionStatusType } from '../types/connection';
import { SlidingToggle } from './ui/ThemeToggle';
import { SearchBar } from './shared/SearchBar';
import { GameState } from '../types/game';

// Auto-save interval in milliseconds (5 minutes)
const AUTO_SAVE_INTERVAL = 5 * 60 * 1000;

interface GameInterfaceProps {
  roomId: string;
  peers: string[];
  connectionStatus: ConnectionStatusType;
  errorMessage: string;
  isRoomCreator: boolean;
  gameState: GameState;
  onLeaveRoom: () => void;
  onSaveGame: () => void;
  onNavigateToResult: (result: {
    id: string;
    type: 'item' | 'skill' | 'character' | 'entity' | 'image';
    location: {
      type: 'catalog' | 'inventory' | 'equipment' | 'field' | 'visuals' | 'encounters';
      containerId?: string;
    };
  }) => void;
  children: ReactNode;
}

export function GameInterface({ 
  roomId,
  isRoomCreator,
  gameState, 
  onLeaveRoom,
  onSaveGame,
  onNavigateToResult,
  children
}: GameInterfaceProps) {

  // Set up auto-save timer for DM
  useEffect(() => {
    if (!isRoomCreator) return;

    console.log('[GameInterface] Starting auto-save timer');
    const autoSaveTimer = setInterval(() => {
      console.log('[GameInterface] Auto-saving game state...');
      onSaveGame();
    }, AUTO_SAVE_INTERVAL);

    return () => {
      console.log('[GameInterface] Cleaning up auto-save timer');
      clearInterval(autoSaveTimer);
    };
  }, [isRoomCreator, onSaveGame]);

  const handleSearchSelect = (result: {
    id: string;
    type: 'item' | 'skill' | 'character' | 'entity' | 'image';
    location: {
      type: 'catalog' | 'inventory' | 'equipment' | 'field' | 'visuals' | 'encounters';
      containerId?: string;
    };
  }) => {
    onNavigateToResult(result);
  };

  return (
    <div className="fixed inset-0 flex flex-col h-[92vh] transition-colors duration-1000 w-screen mt-[8vh] ">
      {/* Header */}
      <div className="flex-shrink-0 p-0">
        <div className="flex items-center justify-between h-[4vh] ml-5  mr-5">
          <div className="flex flex-row gap-0">
            <button
              onClick={onLeaveRoom}
              className="px-3 py-0.5 text-[1.5vmin] bg-grey text-offwhite dark:border-2 border-offwhite rounded-l-md hover:bg-grey/75 dark:hover:bg-offwhite/25 transition-colors"
            >
              Leave Room
            </button>
            {isRoomCreator && (
              <button
                onClick={onSaveGame}
                className="px-3 py-0.5 text-[1.5vmin] bg-offwhite text-grey border-2 dark:border-0 border-grey rounded-r-md hover:bg-grey/25 dark:hover:bg-offwhite/75 transition-colors"
              >
                Save Game
              </button>
            )}
          </div>
          <SearchBar 
            gameState={gameState}
            isRoomCreator={isRoomCreator}
            onResultSelect={handleSearchSelect}
            placeholder="Search items, skills, characters..."
          />
          <div className="darkmode slider">
            <SlidingToggle />
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 min-h-0 h-full">
        {children}
      </div>
    </div>
  );
}