import React, { useState } from 'react';
import { Character, DMViewProps } from '../../../types/game';
import { CharacterEditor } from '../../../components/shared/CharacterEditor';
import { CharacterList } from '../CharacterList';
import Modal from '../../shared/Modal';

export function CharacterTab({ gameState, onGameStateChange, room, isRoomCreator }: DMViewProps) {
  const [selectedCharacterId, setSelectedCharacterId] = useState<string | null>(null);
  const [showEditor, setShowEditor] = useState(false);

  const selectedCharacter = selectedCharacterId 
    ? gameState.party.find(c => c.id === selectedCharacterId)
    : undefined;

  const handleAddCharacter = (character: Omit<Character, 'id'>) => {
    const newId = crypto.randomUUID();
    const newCharacter: Character = {
      ...character,
      id: newId,
    };

    onGameStateChange({
      ...gameState,
      party: [...gameState.party, newCharacter]
    });
    setShowEditor(false);
  };

  const handleUpdateCharacter = (id: string, updates: Partial<Character>) => {
    onGameStateChange({
      ...gameState,
      party: gameState.party.map(char =>
        char.id === id ? { ...char, ...updates } : char
      )
    });
    setShowEditor(false);
  };

  const handleDeleteCharacter = (id: string) => {
    onGameStateChange({
      ...gameState,
      party: gameState.party.filter(char => char.id !== id)
    });
    setShowEditor(false);
  };

  return (
    <div className="flex flex-col h-full">
      {/* Fixed Header with Add Character Button */}
      <div className="flex justify-center items-center pt-4 px-4">
        <button
          onClick={() => {
            setSelectedCharacterId(null);
            setShowEditor(true);
          }}
          className="px-4 py-2 bg-blue dark:bg-cyan text-white dark:text-grey rounded-md transition-colors"
        >
          Add Character
        </button>
      </div>

      {/* Scrollable Character List */}
      <div className="flex-1 overflow-y-auto p-4 px-10">
        <CharacterList
          party={gameState.party}
          onSelectCharacter={(id) => {
            setSelectedCharacterId(id);
            setShowEditor(true);
          }}
          gameState={gameState}
          onGameStateChange={onGameStateChange}
          room={room}
        />

        {/* Empty State */}
        {gameState.party.length === 0 && !showEditor && (
          <div className="text-center py-8 text-gray-500">
            <p>Click "Add Character" to create one!</p>
          </div>
        )}
      </div>

      {/* Character Editor Modal */}
      {showEditor && (
        <Modal
          isOpen={showEditor}
          onClose={() => {
            setShowEditor(false);
            setSelectedCharacterId(null);
          }}
          title={selectedCharacter ? 'Edit Character' : 'Create Character'}
        >
          <CharacterEditor
            character={selectedCharacter}
            onSave={handleAddCharacter}
            onUpdate={handleUpdateCharacter}
            onDelete={handleDeleteCharacter}
            onClose={() => {
              setShowEditor(false);
              setSelectedCharacterId(null);
            }}
            isRoomCreator={true}
          />
        </Modal>
      )}
    </div>
  );
}